const OWNER_EMAIL = "chaumonttheo@gmail.com";

async function main() {
  console.log(`Recherche du owner (${OWNER_EMAIL})...`);
  const { data: users, error: userErr } = await supabase.auth.admin.listUsers({ perPage: 100 });
  if (userErr) throw userErr;
  const owner = users.users.find((u) => u.email === OWNER_EMAIL);
  if (!owner) {
    console.error(`Utilisateur ${OWNER_EMAIL} introuvable.`);
    process.exit(1);
  }
  const ownerId = owner.id;

  const { data: topic } = await supabase.from("cfa_topics").select("id").eq("code", "fixed").maybeSingle();
  const topicId = topic?.id ?? null;

  console.log("Suppression de l'ancien QCM plat 'Revenu Fixe'...");
  await supabase.from("quiz_sets").delete().eq("owner_id", ownerId).eq("title", "Revenu Fixe");

  console.log("Suppression des anciens QCM Fixed Income par sous-thème (si déjà seedés)...");
  const oldTitles = SETS.map((s) => s.title);
  await supabase.from("quiz_sets").delete().eq("owner_id", ownerId).in("title", oldTitles);

  console.log(`Création/recherche du dossier "${FOLDER_NAME}"...`);
  let { data: folder } = await supabase
    .from("library_folders")
    .select("id")
    .eq("name", FOLDER_NAME)
    .eq("kind", "quizzes")
    .eq("owner_id", ownerId)
    .maybeSingle();

  if (!folder) {
    const { data: newFolder, error: folderErr } = await supabase
      .from("library_folders")
      .insert({ name: FOLDER_NAME, kind: "quizzes", owner_id: ownerId })
      .select("id")
      .single();
    if (folderErr) throw folderErr;
    folder = newFolder;
  }

  let total = 0;
  for (const set of SETS) {
    console.log(`\nCréation du set: ${set.title} (${set.questions.length} questions)`);
    const { data: newSet, error: setErr } = await supabase
      .from("quiz_sets")
      .insert({
        title: set.title,
        visibility: "public",
        subject: "cfa",
        owner_id: ownerId,
        folder_id: folder.id,
        is_official: true,
        official_published: true,
        cfa_level: 1,
        difficulty: 1,
      })
      .select("id")
      .single();
    if (setErr) throw setErr;

    const rows = set.questions.map(([prompt, choices, correct_index, explanation], i) => ({
      set_id: newSet.id,
      prompt,
      choices,
      correct_index,
      explanation,
      position: i + 1,
      topic_id: topicId,
    }));

    const { error: qErr } = await supabase.from("quiz_questions").insert(rows);
    if (qErr) throw qErr;

    console.log(`  ✓ ${rows.length} questions insérées (set ${newSet.id})`);
    total += rows.length;
  }

  console.log(`\n✅ Terminé. ${total} questions au total sur ${SETS.length} sets.`);
}

main().catch((e) => {
  console.error("❌ Erreur:", e);
  process.exit(1);
});
